const cfg = $input.first().json;
const chunks = [];

const fmtIso = (d) => {
  const y = d.getUTCFullYear();
  const m = String(d.getUTCMonth() + 1).padStart(2, '0');
  const day = String(d.getUTCDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
};

const hoje = new Date();
hoje.setUTCHours(0, 0, 0, 0);

const inicio = new Date(hoje);
inicio.setUTCDate(inicio.getUTCDate() - (cfg.dias_backfill || 60));

const tamanhoChunk = cfg.tamanho_chunk_dias || 10;

let cursor = new Date(inicio);
while (cursor <= hoje) {
  const fim = new Date(cursor);
  fim.setUTCDate(fim.getUTCDate() + tamanhoChunk - 1);
  if (fim > hoje) fim.setTime(hoje.getTime());

  chunks.push({
    json: { ...cfg, chunk_dtini_iso: fmtIso(cursor), chunk_dtfim_iso: fmtIso(fim), usar_todas: true, is_diario: false }
  });

  cursor = new Date(fim);
  cursor.setUTCDate(cursor.getUTCDate() + 1);
}

return chunks;

const cfg = $input.first().json;
const token = $('1. Transações · Login').first().json.token;
if (!token) throw new Error('Token não encontrado no retorno do /auth');
const todasFlag = cfg.usar_todas ? 'S' : 'N';
const url = `${cfg.url_base}/Transacoes?dtIni=${cfg.chunk_dtini_iso}&dtFim=${cfg.chunk_dtfim_iso}&todas=${todasFlag}`;
return [{ json: { ...cfg, token, url_final: url, bearer_header: `Bearer ${token}`, chunk_inicio_ts: Date.now() } }];

const raw = $input.first().json;
const transacoes = raw.Transacoes || [];

if (transacoes.length === 0) return [];

// 1. MAPEAMENTO ATUALIZADO (Adicionado Garagem e CentroCusto)
const mapa = {
  Transacao: 'transacao',
  DataTransacao: 'data_transacao',
  Hodometro: 'hodometro',
  Valor: 'valor',
  Litragem: 'litragem',
  CodCombustivel: 'cod_combustivel',
  NomeCombustivel: 'nome_combustivel',
  Servico: 'servico',
  TipoAbastecimento: 'tipo_abastecimento',
  CodigoTanque: 'codigo_tanque',
  NomeTanque: 'nome_tanque',
  CodigoBomba: 'codigo_bomba',
  NomeBomba: 'nome_bomba',
  RazaoSocialPosto: 'razao_social_posto',
  NomeFantasiaPosto: 'nome_fantasia_posto',
  CNPJPosto: 'cnpj_posto',
  CidadePosto: 'cidade_posto',
  UFPosto: 'uf_posto',
  CartaoMascarado: 'cartao_mascarado',
  Motorista: 'motorista',
  MatriculaMotorista: 'matricula_motorista',
  CPFMotorista: 'cpf_motorista',
  Placa: 'placa',
  ModeloVeiculo: 'modelo_veiculo',
  AnoVeiculo: 'ano_veiculo',
  MatriculaVeiculo: 'matricula_veiculo',
  MarcaVeiculo: 'marca_veiculo',
  CorVeiculo: 'cor_veiculo',
  TransacaoEstornada: 'transacao_estornada',
  CNPJCliente: 'cnpj_cliente',
  Garagem: 'garagem',           // <--- ADICIONADO
  CentroCusto: 'centro_custo'   // <--- ADICIONADO
};

const colunas = Object.values(mapa);
const colunasNumericas = new Set(['valor', 'litragem']);

const seen = new Map();
for (const tx of transacoes) {
  const obj = {};
  for (const [api, db] of Object.entries(mapa)) {
    obj[db] = tx[api] !== undefined ? tx[api] : null;
  }
  seen.set(obj.transacao, obj);
}
const dedup = Array.from(seen.values());

const CHUNK = 500;
const chunks = [];
for (let i = 0; i < dedup.length; i += CHUNK) chunks.push(dedup.slice(i, i + CHUNK));

const escapar = (v, col) => {
  if (v === null || v === undefined || v === '') return 'NULL';
  if (colunasNumericas.has(col)) {
    const n = parseFloat(String(v).replace(',', '.'));
    return isNaN(n) ? 'NULL' : n;
  }
  return `'${String(v).replace(/'/g, "''")}'`;
};

const conflictCol = 'transacao';
const updateSet = colunas
  .filter(c => c !== conflictCol)
  .map(c => `"${c}" = EXCLUDED."${c}"`)
  .join(',\n  ');

const result = [];
for (const chunk of chunks) {
  const values = chunk.map(row => {
    const vals = colunas.map(c => escapar(row[c], c));
    return `(${vals.join(', ')}, (NOW() AT TIME ZONE 'America/Sao_Paulo'), NULL)`;
  }).join(',\n');

  const sql = `INSERT INTO torre.integration_truckpag_transacoes (
  ${colunas.map(c => `"${c}"`).join(', ')},
  inserido,
  atualizado
)
VALUES ${values}
ON CONFLICT ("${conflictCol}") DO UPDATE SET
  ${updateSet},
  atualizado = (NOW() AT TIME ZONE 'America/Sao_Paulo');`.trim();

  result.push({ json: { sql, qtd_registros: chunk.length } });
}

return result;

const cfg = $input.first().json;
const chunks = [];

const fmtIso = (d) => {
  const y = d.getUTCFullYear();
  const m = String(d.getUTCMonth() + 1).padStart(2, '0');
  const day = String(d.getUTCDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
};

const hoje = new Date();
hoje.setUTCHours(0, 0, 0, 0);

const inicio = new Date(hoje);
inicio.setUTCDate(inicio.getUTCDate() - (cfg.dias_backfill || 60));

const tamanhoChunk = cfg.tamanho_chunk_dias || 10;

let cursor = new Date(inicio);
while (cursor <= hoje) {
  const fim = new Date(cursor);
  fim.setUTCDate(fim.getUTCDate() + tamanhoChunk - 1);
  if (fim > hoje) fim.setTime(hoje.getTime());

  chunks.push({
    json: { ...cfg, chunk_dtini_iso: fmtIso(cursor), chunk_dtfim_iso: fmtIso(fim), usar_todas: true, is_diario: false }
  });

  cursor = new Date(fim);
  cursor.setUTCDate(cursor.getUTCDate() + 1);
}

return chunks;

const cfg = $input.first().json;
const token = $('2. Títulos · Login').first().json.token;
if (!token) throw new Error('Token não encontrado no retorno do /auth');
const todasFlag = cfg.usar_todas ? 'S' : 'N';
const url = `${cfg.url_base}/Faturamento/Titulos?dtIni=${cfg.chunk_dtini_iso}&dtFim=${cfg.chunk_dtfim_iso}&todas=${todasFlag}`;
return [{ json: { ...cfg, token, url_final: url, bearer_header: `Bearer ${token}`, chunk_inicio_ts: Date.now() } }];

// API retorna {"data": "<string JSON>"} ou {"data": [...]} ou array direto
// Esse bloco normaliza as 3 formas
const items = $input.all();
let titulos = [];

for (const item of items) {
  const j = item.json;
  let dados = null;

  if (Array.isArray(j)) {
    dados = j;
  } else if (j && j.data !== undefined) {
    if (typeof j.data === 'string') {
      try {
        dados = JSON.parse(j.data);
      } catch (e) {
        dados = [];
      }
    } else {
      dados = j.data;
    }
  } else if (j && j.titulo_id !== undefined) {
    dados = [j];
  }

  if (Array.isArray(dados)) {
    titulos.push(...dados.filter(t => t && t.titulo_id !== undefined));
  }
}

if (titulos.length === 0) return [];

// === MAPEAMENTO TITULOS (cabeçalho) ===
const mapaTitulos = {
  titulo_id: 'titulo_id',
  data_geracao: 'data_geracao',
  data_vencimento: 'data_vencimento',
  valor_total: 'valor_total'
};
const colsTitulos = Object.values(mapaTitulos);
const colsDataTitulos = new Set(['data_geracao', 'data_vencimento']);
const colsNumericTitulos = new Set(['valor_total']);

// === MAPEAMENTO ITENS ===
const mapaItens = {
  titulo_id: 'titulo_id',
  transacao_id: 'transacao_id',
  tipo: 'tipo',
  valor: 'valor',
  chave_nfe: 'chave_nfe'
};
const colsItens = Object.values(mapaItens);
const colsNumericItens = new Set(['valor']);

// === DEDUP TITULOS (por titulo_id) ===
const seenTitulos = new Map();
const todosItens = [];

for (const t of titulos) {
  const tid = String(t.titulo_id);
  const objT = {
    titulo_id: tid,
    data_geracao: t.data_geracao || null,
    data_vencimento: t.data_vencimento || null,
    valor_total: t.valor_total !== undefined ? t.valor_total : null
  };
  seenTitulos.set(tid, objT);

  const itens = Array.isArray(t.itens) ? t.itens : [];
  for (const it of itens) {
    todosItens.push({
      titulo_id: tid,
      transacao_id: it.transacao_id !== undefined ? String(it.transacao_id) : null,
      tipo: it.tipo || null,
      valor: it.valor !== undefined ? it.valor : null,
      chave_nfe: it.chave_nfe || null
    });
  }
}

const titulosDedup = Array.from(seenTitulos.values());

// === DEDUP ITENS (por titulo_id + transacao_id) ===
const seenItens = new Map();
for (const it of todosItens) {
  if (!it.transacao_id) continue;
  const key = `${it.titulo_id}::${it.transacao_id}`;
  seenItens.set(key, it);
}
const itensDedup = Array.from(seenItens.values());

const escTitulos = (v, col) => {
  if (v === null || v === undefined || v === '') return 'NULL';
  if (colsDataTitulos.has(col)) {
    // Adiciona as 3 horas perdidas na string da data antes de mandar pro banco
    return `'${String(v).replace(/'/g, "''")} 03:00:00+00'::timestamptz`;
  }
  if (colsNumericTitulos.has(col)) {
    const n = parseFloat(String(v).replace(',', '.'));
    return isNaN(n) ? 'NULL' : n;
  }
  return `'${String(v).replace(/'/g, "''")}'`;
};

const escItens = (v, col) => {
  if (v === null || v === undefined || v === '') return 'NULL';
  if (colsNumericItens.has(col)) {
    const n = parseFloat(String(v).replace(',', '.'));
    return isNaN(n) ? 'NULL' : n;
  }
  return `'${String(v).replace(/'/g, "''")}'`;
};

// === Gerar SQL para TITULOS ===
let sqlTitulos = null;
if (titulosDedup.length > 0) {
  const conflictColT = 'titulo_id';
  const updateSetT = colsTitulos
    .filter(c => c !== conflictColT)
    .map(c => `"${c}" = EXCLUDED."${c}"`)
    .join(',\n  ');

  const valuesT = titulosDedup.map(row => {
    const vals = colsTitulos.map(c => escTitulos(row[c], c));
    return `(${vals.join(', ')}, NOW(), NULL)`;
  }).join(',\n');

  sqlTitulos = `INSERT INTO torre.integration_truckpag_titulos (
  ${colsTitulos.map(c => `"${c}"`).join(', ')},
  created_at,
  updated_at
)
VALUES ${valuesT}
ON CONFLICT ("${conflictColT}") DO UPDATE SET
  ${updateSetT},
  updated_at = NOW();`.trim();
}

// === Gerar SQL para ITENS ===
let sqlItens = null;
if (itensDedup.length > 0) {
  const conflictColsI = ['titulo_id', 'transacao_id'];
  const updateSetI = colsItens
    .filter(c => !conflictColsI.includes(c))
    .map(c => `"${c}" = EXCLUDED."${c}"`)
    .join(',\n  ');

  const valuesI = itensDedup.map(row => {
    const vals = colsItens.map(c => escItens(row[c], c));
    return `(${vals.join(', ')}, NOW(), NULL)`;
  }).join(',\n');

  sqlItens = `INSERT INTO torre.integration_truckpag_titulo_itens (
  ${colsItens.map(c => `"${c}"`).join(', ')},
  created_at,
  updated_at
)
VALUES ${valuesI}
ON CONFLICT (${conflictColsI.map(c => `"${c}"`).join(', ')}) DO UPDATE SET
  ${updateSetI},
  updated_at = NOW();`.trim();
}

return [{
  json: {
    sql_titulos: sqlTitulos,
    sql_itens: sqlItens,
    qtd_titulos: titulosDedup.length,
    qtd_itens: itensDedup.length,
    qtd_registros: titulosDedup.length + itensDedup.length
  }
}];

const cfg = $input.first().json;
const chunks = [];

const fmtIso = (d) => {
  const y = d.getUTCFullYear();
  const m = String(d.getUTCMonth() + 1).padStart(2, '0');
  const day = String(d.getUTCDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
};

const hoje = new Date();
hoje.setUTCHours(0, 0, 0, 0);

const inicio = new Date(hoje);
inicio.setUTCDate(inicio.getUTCDate() - (cfg.dias_backfill || 60));

const tamanhoChunk = cfg.tamanho_chunk_dias || 10;

let cursor = new Date(inicio);
while (cursor <= hoje) {
  const fim = new Date(cursor);
  fim.setUTCDate(fim.getUTCDate() + tamanhoChunk - 1);
  if (fim > hoje) fim.setTime(hoje.getTime());

  chunks.push({
    json: { ...cfg, chunk_dtini_iso: fmtIso(cursor), chunk_dtfim_iso: fmtIso(fim), usar_todas: true, is_diario: false }
  });

  cursor = new Date(fim);
  cursor.setUTCDate(cursor.getUTCDate() + 1);
}

return chunks;

const cfg = $input.first().json;
const token = $('3. NFe Vínculos · Login').first().json.token;
if (!token) throw new Error('Token não encontrado no retorno do /auth');
const todasFlag = cfg.usar_todas ? 'S' : 'N';
const url = `${cfg.url_base}/NotaFiscal/Vinculo?dtIni=${cfg.chunk_dtini_iso}&dtFim=${cfg.chunk_dtfim_iso}&todas=${todasFlag}`;
return [{ json: { ...cfg, token, url_final: url, bearer_header: `Bearer ${token}`, chunk_inicio_ts: Date.now() } }];

// Coletar todos os items que chegaram do GET (array no root da API)
const items = $input.all();
const vinculos = items.map(i => i.json).filter(v => v && v.IdTransacao);

if (vinculos.length === 0) return [];

// Mapa API (PascalCase) -> coluna do banco (snake_case)
// CORRIGIDO: incluídos numero_nfe, valor_total, data_emissao, cnpj_destinatario
// e 'Operacao' com O maiúsculo (é assim que a API envia).
const mapa = {
  IdTransacao:      'id_transacao',
  ChaveNFe:         'chave_nfe',
  NumeroNFe:        'numero_nfe',
  VlTotal:          'valor_total',
  DtEmissao:        'data_emissao',
  CnpjDestinatario: 'cnpj_destinatario',
  VctoPrevisto:     'vencimento_previsto',
  Operacao:         'operacao'
};

const colunas = Object.values(mapa);
const colunasData    = new Set(['data_emissao', 'vencimento_previsto']); // ::timestamptz
const colunasNumeric = new Set(['valor_total']);                          // ::numeric

// Dedup pelo id_transacao (chave única); última ocorrência prevalece
const seen = new Map();
for (const v of vinculos) {
  const obj = {};
  for (const [api, db] of Object.entries(mapa)) {
    obj[db] = v[api] !== undefined ? v[api] : null;
  }
  seen.set(String(obj.id_transacao), obj);
}
const dedup = Array.from(seen.values());

const CHUNK = 500;
const chunks = [];
for (let i = 0; i < dedup.length; i += CHUNK) chunks.push(dedup.slice(i, i + CHUNK));

const escapar = (v, col) => {
  if (v === null || v === undefined || v === '') return 'NULL';
  if (colunasData.has(col)) {
    return `'${String(v).replace(/'/g, "''")}'::timestamptz`;
  }
  if (colunasNumeric.has(col)) {
    // troca vírgula decimal por ponto, por segurança de locale
    const num = String(v).replace(',', '.').replace(/'/g, "''");
    return `'${num}'::numeric`;
  }
  return `'${String(v).replace(/'/g, "''")}'`;
};

const conflictCol = 'id_transacao';
const updateSet = colunas
  .filter(c => c !== conflictCol)
  .map(c => `"${c}" = EXCLUDED."${c}"`)
  .join(',\n  ');

const result = [];
for (const chunk of chunks) {
  const values = chunk.map(row => {
    const vals = colunas.map(c => escapar(row[c], c));
    return `(${vals.join(', ')}, NOW(), NULL)`;
  }).join(',\n');

  const sql = `INSERT INTO torre.integration_truckpag_nfe_vinculos (
  ${colunas.map(c => `"${c}"`).join(', ')},
  created_at,
  updated_at
)
VALUES ${values}
ON CONFLICT ("${conflictCol}") DO UPDATE SET
  ${updateSet},
  updated_at = NOW();`.trim();

  result.push({
  json: { sql, qtd_registros: chunk.length },
  pairedItem: { item: 0 }
});
}

return result;
